// Word timings for every spoken line (generated by scripts/generate-voice.mts).
import v1 from "../public/audio/vo/v1-guess.json";
import v2 from "../public/audio/vo/v2-meet.json";
import v3 from "../public/audio/vo/v3-laser.json";
import v4 from "../public/audio/vo/v4-sense.json";
import v5 from "../public/audio/vo/v5-knock.json";
import v6 from "../public/audio/vo/v6-talk.json";
import v7 from "../public/audio/vo/v7-options.json";
import v8 from "../public/audio/vo/v8-close.json";
import { VO_AT } from "./timing";

export type Word = { text: string; start: number; end: number };
export type VoClip = { id: string; text: string; duration: number; words: Word[] };

const CLIPS = [v1, v2, v3, v4, v5, v6, v7, v8] as VoClip[];

export const VO: Record<string, VoClip> = Object.fromEntries(CLIPS.map((c) => [c.id, c]));

// Absolute time (seconds) when word `index` of clip `id` starts.
export const wordAt = (id: string, index: number) => VO_AT[id] + VO[id].words[index].start;

// Absolute time when the first word containing `needle` starts in clip `id`.
export const wordTime = (id: string, needle: string) => {
  const i = VO[id].words.findIndex((w) => w.text.toLowerCase().includes(needle.toLowerCase()));
  if (i < 0) throw new Error(`"${needle}" not found in ${id}`);
  return wordAt(id, i);
};
